CATS = [
    {'id': 'sira',   'name': 'السيرة النبوية'},
    {'id': 'hadith', 'name': 'الأحاديث الصحيحة'},
]

H_NOTE = ('أحاديثُ هذا القسم من «صحيح البخاريّ» و«صحيح مسلم» وحدَهما، ونصُّ كلِّ حديثٍ منقولٌ من الكتاب نفسِه، '
          'ومكتوبٌ تحته الكتابُ الذي رواه والصحابيُّ راويه. والشرحُ مختصَرٌ لتقريب المعنى، ولا يغني عن كتب الشروح وأهل العلم.')

def theme(id_, title, sub, blocks):
    return {'id': id_, 'cat': 'hadith', 't': title, 'sub': sub, 'ic': IC_BOOK,
            'blocks': [{'k': 'note', 'tone': 'info', 'v': H_NOTE}] + blocks}

