S_NOTE = ('تُروى السيرةُ من مصدرين: القرآنِ والصحيحِ من السنّة، وكتبِ السِّيَر (ابن إسحاق برواية ابن هشام، وابن سعد، وابن كثير). '
          'وما جاء في الصحيحين نُصّ فيه على «المصدر» تحت النصّ، وما سوى ذلك فمن كتب السير، وقد نُبِّه على الخلاف حيث وقع.')

def sira(id_, title, sub, blocks, src):
    SRC[id_] = src
    return {'id': id_, 'cat': 'sira', 't': title, 'sub': sub, 'ic': IC_PIN,
            'blocks': [{'k': 'note', 'tone': 'info', 'v': S_NOTE}] + blocks}

SRC = {}
SB = lambda t, d=None: {'k': 's', 't': t, 'd': d} if d else {'k': 's', 't': t}
SQ = lambda t, d=None: {'k': 'q', 't': t, 'd': d} if d else {'k': 'q', 't': t}
SH = lambda t, d=None: {'k': 'h', 't': t, 'd': d} if d else {'k': 'h', 't': t}
SN = lambda t, d=None: {'k': 'n', 't': t, 'd': d} if d else {'k': 'n', 't': t}
